180→// querySessionID queries the SQLite database for the most recent conversation ID
181→// associated with the given CWD.
182→func (k *KiroAgent) querySessionID(ctx context.Context, cwd string) (string, error) {
183→	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
184→		return "mock-session-id", nil
185→	}
186→
187→	db, err := dbPath()
188→	if err != nil {
189→		return "", err
190→	}
191→	if _, err := os.Stat(db); err != nil {
192→		return "", fmt.Errorf("kiro database not found at %s: %w", db, err)
193→	}
194→
195→	query := fmt.Sprintf(
196→		"SELECT json_extract(value, '$.conversation_id') FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
197→		strings.ReplaceAll(cwd, "'", "''"),
198→	)
199→
200→	cmd := exec.CommandContext(ctx, "sqlite3", "-json", db, query)
201→	out, err := cmd.Output()
202→	if err != nil {
203→		logging.Warn(ctx, "kiro: sqlite3 query failed", "err", err, "cwd", cwd)
204→		return "", fmt.Errorf("sqlite3 query failed: %w", err)
205→	}
206→
207→	result := strings.TrimSpace(string(out))
208→	if result == "" || result == "[]" {
209→		return "", nil
210→	}
211→
212→	// sqlite3 -json returns an array of objects
213→	var rows []map[string]string
214→	if err := json.Unmarshal([]byte(result), &rows); err != nil {
215→		return "", fmt.Errorf("failed to parse sqlite3 output: %w", err)
216→	}
217→	if len(rows) == 0 {
218→		return "", nil
219→	}
220→
221→	// The column name from json_extract
222→	for _, v := range rows[0] {
223→		return v, nil
224→	}
225→	return "", nil
226→}
