239→	// Fetch fresh transcript from SQLite on every call (transcript grows during session)
240→	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
241→		// In test mode, return cache path if it exists, or empty
242→		if _, err := os.Stat(cachePath); err == nil {
243→			return cachePath, nil
244→		}
245→		return cachePath, nil
246→	}
247→
248→	db, err := dbPath()
249→	if err != nil {
250→		return "", err
251→	}
252→
253→	query := fmt.Sprintf(
254→		"SELECT value FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
255→		strings.ReplaceAll(cwd, "'", "''"),
256→	)
257→
258→	cmd := exec.CommandContext(ctx, "sqlite3", db, query)
259→	out, err := cmd.Output()
260→	if err != nil {
261→		return "", fmt.Errorf("sqlite3 transcript query failed: %w", err)
262→	}
263→
264→	transcript := strings.TrimSpace(string(out))
265→	if transcript == "" {
266→		return "", errors.New("no transcript found")
267→	}
268→
269→	if err := os.MkdirAll(cacheDir, 0o750); err != nil {
270→		return "", fmt.Errorf("failed to create cache dir: %w", err)
271→	}
272→
273→	if err := os.WriteFile(cachePath, []byte(transcript), 0o600); err != nil {
274→		return "", fmt.Errorf("failed to write cached transcript: %w", err)
275→	}
276→
277→	return cachePath, nil
278→}
